-- Data madrasah DKI Jakarta untuk tabel `madrasah` (si_jmc).
-- Sumber: si_presma/database/seeders/data/madrasahs2.sql (1816 baris).
-- 1 baris dilewati karena NPSN kosong: MI DARUL QUWWAH (Srengseng Sawah, Jakarta Selatan).
-- Aman dijalankan ulang: baris dengan NPSN yang sama akan diperbarui.
-- Dijalankan oleh: php artisan db:seed --class=MadrasahSeeder

ON DUPLICATE KEY UPDATE
  `nama` = VALUES(`nama`), `jenjang` = VALUES(`jenjang`), `status` = VALUES(`status`),
  `provinsi` = VALUES(`provinsi`), `kota` = VALUES(`kota`), `kecamatan` = VALUES(`kecamatan`),
  `kelurahan` = VALUES(`kelurahan`), `alamat_sekolah` = VALUES(`alamat_sekolah`), `updated_at` = NOW();
